const isBiz=d=>d.getUTCDay()%6!==0;const addBiz=(d,n)=>{const x=new Date(d);const s=n<0?-1:1;let k=Math.abs(n);while(k>0){x.setUTCDate(x.getUTCDate()+s);if(isBiz(x))k--}return x};
