const FEATS=[['r1',()=>L('عائد يوم','1-bar return')],['r5',()=>L('عائد ٥','5-bar return')],['r20',()=>L('عائد ٢٠','20-bar return')],['rsi',()=>'RSI 14'],['d20',()=>L('البعد عن متوسط ٢٠','Distance from SMA 20')],['d50',()=>L('البعد عن متوسط ٥٠','Distance from SMA 50')],['d200',()=>L('البعد عن متوسط ٢٠٠','Distance from SMA 200')],['atr',()=>L('التذبذب (ATR%)','Volatility (ATR%)')],['vz',()=>L('الحجم مقابل المعتاد','Volume vs normal')]];
function featurize(b,H,keys){const c=b.map(x=>x.close),v=b.map(x=>x.volume||0),R=rsiArr(c),X=[],Y=[],T=[];
 for(let i=200;i<b.length;i++){let tr=0;for(let j=i-13;j<=i;j++)tr+=Math.max(b[j].high-b[j].low,Math.abs(b[j].high-c[j-1]),Math.abs(b[j].low-c[j-1]));const vm=sma(v,20,i),vs=Math.sqrt(v.slice(i-19,i+1).reduce((s,x)=>s+(x-vm)**2,0)/20)||1;
  const F={r1:c[i]/c[i-1]-1,r5:c[i]/c[i-5]-1,r20:c[i]/c[i-20]-1,rsi:(R[i]-50)/50,d20:c[i]/sma(c,20,i)-1,d50:c[i]/sma(c,50,i)-1,d200:c[i]/sma(c,200,i)-1,atr:tr/14/c[i],vz:(v[i]-vm)/vs};
  X.push(keys.map(k=>F[k]));T.push(b[i].time);Y.push(i+H<b.length?(c[i+H]>c[i]?1:0):null)}return {X,Y,T,c:c.slice(200)}}
function standardize(X,n){const d=X[0].length,mu=Array(d).fill(0),sd=Array(d).fill(0);for(let i=0;i<n;i++)X[i].forEach((v,j)=>mu[j]+=v/n);for(let i=0;i<n;i++)X[i].forEach((v,j)=>sd[j]+=(v-mu[j])**2/n);return X.map(r=>r.map((v,j)=>(v-mu[j])/(Math.sqrt(sd[j])||1)))}
function logit(X,Y,n){const d=X[0].length;let w=Array(d).fill(0),b0=0;const sig=z=>1/(1+Math.exp(-z));for(let ep=0;ep<300;ep++){const g=Array(d).fill(0);let gb=0;for(let i=0;i<n;i++){const e=sig(b0+X[i].reduce((s,v,j)=>s+v*w[j],0))-Y[i];gb+=e;X[i].forEach((v,j)=>g[j]+=e*v)}w=w.map((x,j)=>x-.5*(g[j]/n+.01*x));b0-=.5*gb/n}return {w,b0,p:x=>sig(b0+x.reduce((s,v,j)=>s+v*w[j],0))}}
